import{_ as t,o as a,c as s,ag as o}from"./chunks/framework.em2JOrjF.js";const h=JSON.parse('{"title":"Reporting Sheet","description":"","frontmatter":{},"headers":[],"relativePath":"reporting/index.md","filePath":"reporting/index.md"}'),n={name:"reporting/index.md"};function r(i,e,c,d,l,p){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="reporting-sheet" tabindex="-1">Reporting Sheet <a class="header-anchor" href="#reporting-sheet" aria-label="Permalink to &quot;Reporting Sheet&quot;">​</a></h1><p>The reporting spreadsheet is a <strong>separate Google file</strong> from the database. It contains human-facing dashboards built with Google Sheets formulas. The bot never reads or writes this file.</p><hr><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Database Sheet (bot reads/writes)</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>   IMPORTRANGE (via IMPORT_DB named function)</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Hidden mirror sheets (one per database tab)</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Visible dashboard tabs (built with LET/FILTER/MAP formulas)</span></span></code></pre></div><p>Each database tab is mirrored into a hidden sheet in the reporting spreadsheet. Visible dashboard tabs pull from these mirrors — not directly from the database sheet.</p><hr><h2 id="import-db-formulas" tabindex="-1">IMPORT_DB formulas <a class="header-anchor" href="#import-db-formulas" aria-label="Permalink to &quot;IMPORT_DB formulas&quot;">​</a></h2><p>Place in cell A1 of each hidden mirror sheet:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>01. Time Entries:     =IMPORT_DB(&quot;01. Time Entries!A:H&quot;)</span></span>
<span class="line"><span>02. Projects:         =IMPORT_DB(&quot;02. Projects!A:L&quot;)</span></span>
<span class="line"><span>03. Users:            =IMPORT_DB(&quot;03. Users!A:G&quot;)</span></span>
<span class="line"><span>04. Clients:          =IMPORT_DB(&quot;04. Clients!A:D&quot;)</span></span>
<span class="line"><span>05. Tasks:            =IMPORT_DB(&quot;05. Tasks!A:C&quot;)</span></span>
<span class="line"><span>06. Project_Tasks:    =IMPORT_DB(&quot;06. Project_Tasks!A:D&quot;)</span></span>
<span class="line"><span>07. Budgets:          =IMPORT_DB(&quot;07. Budgets!A:I&quot;)</span></span>
<span class="line"><span>08. Disciplines:      =IMPORT_DB(&quot;08. Disciplines!A:C&quot;)</span></span>
<span class="line"><span>10. Pending_PTO:      =IMPORT_DB(&quot;10. Pending_PTO!A:I&quot;)</span></span>
<span class="line"><span>11. Unresolved_Items: =IMPORT_DB(&quot;11. Unresolved_Items!A:I&quot;)</span></span>
<span class="line"><span>12. Company_Calendar: =IMPORT_DB(&quot;12. Company_Calendar!A:D&quot;)</span></span>
<span class="line"><span>13. Rate_History:     =IMPORT_DB(&quot;13. Rate_History!A:D&quot;)</span></span>
<span class="line"><span>14. Liabilities:      =IMPORT_DB(&quot;14. Liabilities!A:H&quot;)</span></span>
<span class="line"><span>22. Projects Master:  =IMPORT_DB(&quot;&#39;22. Projects Master&#39;!A:P&quot;)</span></span></code></pre></div><p><code>IMPORT_DB</code> is a named function wrapping <code>IMPORTRANGE</code> with the database sheet URL. Only <code>22. Projects Master</code> uses single quotes inside the string.</p><hr><h2 id="dashboard-tabs" tabindex="-1">Dashboard tabs <a class="header-anchor" href="#dashboard-tabs" aria-label="Permalink to &quot;Dashboard tabs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tab</th><th>Purpose</th></tr></thead><tbody><tr><td><code>00. Dashboard</code></td><td>KPI cards + portfolio health table</td></tr><tr><td><code>01. Summary</code></td><td>Client-level aggregation</td></tr><tr><td><code>02. Projects Master</code></td><td>Full project list with financials</td></tr><tr><td><code>03. Project Performance</code></td><td>Per-project delivery metrics</td></tr><tr><td><code>04. FP Variance</code></td><td>Fixed Price margin analysis</td></tr><tr><td><code>05. Retainer Analysis</code></td><td>Burn rate and hours remaining</td></tr><tr><td><code>06. League Table</code></td><td>PM performance rankings</td></tr><tr><td><code>07. Financials</code></td><td>Revenue, cost, margin by project type</td></tr><tr><td><code>08. Historical</code></td><td>Rolling 12-month trends</td></tr><tr><td><code>09. Rate Tables</code></td><td>Rate history per team member</td></tr><tr><td><code>10. Export</code></td><td>Raw time entries with resolved names</td></tr></tbody></table><p>See the column headers and formula patterns for each tab below.</p><hr><h2 id="tab-headers" tabindex="-1">Tab headers <a class="header-anchor" href="#tab-headers" aria-label="Permalink to &quot;Tab headers&quot;">​</a></h2><p><strong>00. Dashboard</strong></p><blockquote><p>Project Name, Client, Type, Hours Logged, Hours Budget, % Budget Used, Health Status</p></blockquote><p><strong>01. Summary</strong></p><blockquote><p>Client Name, Active Projects, Total Hours Logged, Total Hours Budget, % Budget Used</p></blockquote><p><strong>02. Projects Master</strong></p><blockquote><p>Project Name, Client, Project Type, Billable, Contract Value ($), Hours Budget, Actual Hours, Labor Cost ($), Hour Variance (hrs), Cost Variance ($), Variance %, Billing Rate ($/hr)</p></blockquote><p><strong>03. Project Performance</strong></p><blockquote><p>Project Name, Client, Project Type, Hours Logged, Hours Budget, % Budget Used, Hour Variance, Cost Variance ($), Health Status</p></blockquote><p><strong>04. FP Variance</strong></p><blockquote><p>Project Name, Client, Contract Value ($), Hours Budget, Actual Hours, % Complete, Earned Revenue ($), Actual Cost ($), Margin ($), Margin Variance ($)</p></blockquote><p><strong>05. Retainer Analysis</strong></p><blockquote><p>Project Name, Client, Contract Value ($), Hours Budget, Hours Used, Burn Rate, Hours Remaining</p></blockquote><p><strong>06. League Table</strong></p><blockquote><p>Project Manager, Active Projects, Under Budget, Under Budget %, At Warning, Warning %, Over Budget, Over Budget %, Avg Utilisation, Performance Score</p></blockquote><p><strong>07. Financials</strong></p><blockquote><p>Project Name, Client, Project Type, Billable, Contract Value ($), Hours Logged, Revenue ($), Cost ($), Margin ($), Margin %</p></blockquote><p><strong>08. Historical</strong></p><blockquote><p>Month, Total Hours, Time Entries, Avg Hours per Entry</p></blockquote><p><strong>09. Rate Tables</strong></p><blockquote><p>Team Member, Employment Type, Hourly Cost ($), Effective From</p></blockquote><p><strong>10. Export</strong></p><blockquote><p>Date, Team Member, Project Name, Task Name, Hours Logged, Notes, Billable</p></blockquote><hr><h2 id="percentage-convention" tabindex="-1">Percentage convention <a class="header-anchor" href="#percentage-convention" aria-label="Permalink to &quot;Percentage convention&quot;">​</a></h2><p>All formulas output percentages as <strong>decimals</strong> (e.g. <code>0.85</code>, not <code>85</code>). Format the column as &quot;Percent&quot; in Google Sheets to display as <code>85%</code>.</p><p>Threshold comparisons use <code>pct &gt;= threshold/100</code> (thresholds are stored as whole numbers like <code>80</code>). Over-budget = <code>pct &gt;= 1</code>.</p><hr><h2 id="status-values" tabindex="-1">Status values <a class="header-anchor" href="#status-values" aria-label="Permalink to &quot;Status values&quot;">​</a></h2><p>The Projects Master <code>status</code> column uses <code>&quot;Active&quot;</code> (capital A). The <code>02. Projects</code> sheet uses <code>&quot;active&quot;</code> (lowercase).</p><ul><li>FILTER <code>=</code> is case-insensitive — both work</li><li>QUERY <code>WHERE</code> is case-sensitive — use <code>&#39;Active&#39;</code> not <code>&#39;active&#39;</code> in QUERY clauses</li></ul><p>See <a href="/vera-docs/reporting/formula-rules.html">Formula Rules</a> for the full list of Google Sheets constraints.</p>`,48)])])}const g=t(n,[["render",r]]);export{h as __pageData,g as default};
